package com.bank.decorator;

import java.math.BigDecimal;
import java.util.logging.Logger;

interface AccountFeature {                 // shared interface
    BigDecimal monthlyFee();
    String describe();
}

class BasicAccount implements AccountFeature {   // base component
    public BigDecimal monthlyFee() { return new BigDecimal("100"); }
    public String describe() { return "Basic"; }
}

abstract class FeatureDecorator implements AccountFeature {
    protected final AccountFeature wrapped;      // holds the component it decorates
    FeatureDecorator(AccountFeature wrapped) { this.wrapped = wrapped; }
}

class OverdraftFeature extends FeatureDecorator {
    OverdraftFeature(AccountFeature w) { super(w); }
    public BigDecimal monthlyFee() { return wrapped.monthlyFee().add(new BigDecimal("50")); }
    public String describe() { return wrapped.describe() + " + Overdraft"; }
}

class RewardsFeature extends FeatureDecorator {
    RewardsFeature(AccountFeature w) { super(w); }
    public BigDecimal monthlyFee() { return wrapped.monthlyFee().add(new BigDecimal("75")); }
    public String describe() { return wrapped.describe() + " + Rewards"; }
}

public class DecoratorDemo {
    public static void main(String[] args) {
        Logger log = Logger.getLogger("ACC");
        // Rajesh stacks overdraft and rewards onto a basic account
        AccountFeature rajesh = new RewardsFeature(new OverdraftFeature(new BasicAccount()));
        log.info(rajesh.describe() + " monthly fee = " + rajesh.monthlyFee());
    }
}
